import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"27、【頤】 震下艮上","description":"周易集註 - 27、【頤】 震下艮上","frontmatter":{"title":"27、【頤】 震下艮上","description":"周易集註 - 27、【頤】 震下艮上"},"headers":[],"relativePath":"classics/jizhu/031.md","filePath":"classics/jizhu/031.md"}'),t={name:"classics/jizhu/031.md"};function h(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_27、【頤】-震下艮上" tabindex="-1">27、【頤】 震下艮上 <a class="header-anchor" href="#_27、【頤】-震下艮上" aria-label="Permalink to “27、【頤】 震下艮上”">​</a></h1><p>頤，口旁也。食物以自養，故取養義。為卦上下二陽，內含四陰，外實內虛，上止下動，故名為頤。《序卦》“物畜然後可養，故受之以頤”，所以次大畜。</p><p>夲卦大象離目，觀之象也。陽實陰虛，實者養人，虛者求人之養，自求口實者。自求養於陽之實也。震不求艮，艮不求震，惟自求同體之陽，故曰自求。爻辭見之。</p><p>《彖》曰：頤，貞吉，養正則吉也。觀頤，觀其所養也。自求口實，觀其自養也。天地養萬物，聖人養賢以及萬民，頤之時大矣哉。</p><p>釋卦辭。極言養道而贊之。觀其所養者，觀其所以養人之道正不正也，指上下二陽也。觀其自養者，觀其求口實以自養之正不正也，指中間四陰也。本卦頤，原從口無養德之意，惟頤養得正，則養德即在其中矣。不但養人自養，以至天地聖人養萬物，養萬民，無非養之所在，故曰頤之時大矣哉。與大過解革同。</p><h3 id="《象》曰-山下有雷-頤-君子以慎言語-節飲食。" tabindex="-1">《象》曰：山下有雷，頤，君子以慎言語，節飲食。 <a class="header-anchor" href="#《象》曰-山下有雷-頤-君子以慎言語-節飲食。" aria-label="Permalink to “《象》曰：山下有雷，頤，君子以慎言語，節飲食。”">​</a></h3><p>帝出乎震，萬物得養而生成。言乎艮，萬物得養而成。君子慎言語以養其德，節飲食以養其體，言語飲食動之象慎也。節也，止之象。此處方說出養德。</p><p>初九，舍爾靈龜，觀我朵頤，兇。舍，音舍</p><p>大象離，龜之象也。應爻艮止中空，靈龜止而不食，服氣空腹之象也。朵者，垂朵也。震反生，朵之象也。垂下其頤以垂涎，乃欲食之貌也。爾者，四也。我者，初也。靈龜以靜止為養，朵頤以震動為養，故爾四而我初。大象離目，又觀之象也。</p><p>初九陽剛乃養人者也，但其位卑下，不能養人及民，又乃動體，當頤養之初，正上止下動之時。惟知有口體之慾，舍六四而不養，故有舍爾靈龜，觀我朵頤之象。飲食，人賤兇之道也，故其佔如此。</p><h3 id="《象》曰-觀我朵頤-亦不足貴也。" tabindex="-1">《象》曰：觀我朵頤，亦不足貴也。 <a class="header-anchor" href="#《象》曰-觀我朵頤-亦不足貴也。" aria-label="Permalink to “《象》曰：觀我朵頤，亦不足貴也。”">​</a></h3><p>飲食之人，則人賤之，故不足貴。</p><p>六二，顛頤，拂經，於丘頤，徵兇。</p><p>顛者，頂也。指外卦也。拂者，除也，去也，違悖之意。諸爻皆求養於統體之陽，不從應與，故有顛拂之象。顛頤者，求養於上也。拂經者，違悖養於同體之常經也。山阜曰：丘土之高者，艮之象也。於丘頤者，求養於外，即顛頤也。兇者，求食於權門，必見拒而取羞也。</p><p>六二陰柔，不能自養，必待養於陽剛。然震性妄動，不求養於初，而求養於外，則違養道之常理而行失其類矣。故教佔者，當求養於初。若於丘頤，不惟不得其養，而往則兇也。故其象佔如此。</p><h3 id="《象》曰-六二徵兇-行失類也。" tabindex="-1">《象》曰：六二徵兇，行失類也。 <a class="header-anchor" href="#《象》曰-六二徵兇-行失類也。" aria-label="Permalink to “《象》曰：六二徵兇，行失類也。”">​</a></h3><p>養道各從其類，二三養於初，四五養於上，今二顛頤，往失其類矣，故曰失類。曰行者，震足之象也。</p><p>六三，拂頤，貞兇。十年勿用，無攸利。</p><p>拂頤者，違拂所養之道，不求養於初，而求養於上之正應也。貞者，正也。上乃正應，亦非不正也。十年者，中爻坤，土之成數也。勿用者，不得用其養也。口容止所以下三爻養於動者，皆兇。上三爻養於止者，皆吉。</p><p>六三陰柔，不中正，本乃動體，至三則動極而妄動矣，故有拂頤之象。佔者得此，雖正亦兇。至於十年之久。理極數窮，亦不可往，其兇至此。</p><h3 id="《象》曰-十年勿用-道大悖也。" tabindex="-1">《象》曰：十年勿用，道大悖也。 <a class="header-anchor" href="#《象》曰-十年勿用-道大悖也。" aria-label="Permalink to “《象》曰：十年勿用，道大悖也。”">​</a></h3><p>震為大塗，道之象也，大悖，即拂頤。</p><p>六四，顛頤，吉，虎視眈眈，其欲逐逐，無咎。耽，都含切</p><p>顛者，頂也，與六二同。顛頤者，求養於上也。吉者，得養道之常經也。艮為虎，虎之象也。天下之物，自養於內者莫如龜，求養於外者莫如虎。龜自養於內，內卦初舍之，故兇。虎求養於外，外卦上施之，故吉。爻辭之精至此。耽者，視近而志遠也。變離目，視之象也。應爻初為地位，虎行垂首下視於地，視近也。而心志乃求養於天位之上，志遠也，故以耽字言之。視下卦，耽也。志上卦，耽也。故曰耽耽。陰者，人慾之象也。下卦二陰欲也。上卦二陰，欲也。人慾重疊追逐而來，故曰逐逐。耽者，四求養於上也。逐者，上施養於四也。</p><p>六四當頤養之時，求養於上，故有顛頤之象，吉之道也。故佔者吉。然四求養於上，上施養於四。四得所養矣，故又有視耽欲逐之象。以求養而得逐逐之慾，似有過咎矣。然養得其正，故佔者不惟吉，而又無咎也。</p><h3 id="《象》曰-顛頤之吉-上施光也。施去聲" tabindex="-1">《象》曰：顛頤之吉，上施光也。施去聲 <a class="header-anchor" href="#《象》曰-顛頤之吉-上施光也。施去聲" aria-label="Permalink to “《象》曰：顛頤之吉，上施光也。施去聲”">​</a></h3><p>施者及也。佈散惠與之義，詳見乾卦“雲行雨施”，言上養及於四也。光者，艮篤實，光輝其道，光明也。變離日，亦光之象也。</p><p>六五，拂經，居貞吉，不可涉大川。</p><p>拂經者，五與內卦為正應，亦如二之求養於上，違悖養於同體之常道也。故二五皆言拂經，居者靜以守之也，貞者求養於同體之陽，乃任賢養民之正道也。吉者，恩不自出而又能養人也。不可涉大川者，言不可自用以濟人也。涉川必乾剛，五柔故不可涉。</p><p>六五居尊，能自養人者也。但陰柔不正，無養人之才，又與內卦為正應，亦有拂經之象。然養賢及民，君道之正，故教佔者順以從上，守此正道則吉，不可不量己之力而當濟人之任也。</p><h3 id="《象》曰-居貞之吉-順以從上也。" tabindex="-1">《象》曰：居貞之吉，順以從上也。 <a class="header-anchor" href="#《象》曰-居貞之吉-順以從上也。" aria-label="Permalink to “《象》曰：居貞之吉，順以從上也。”">​</a></h3><p>中爻坤順，故曰順。言順從上而養人也。</p><p>上九，由頤，厲，吉，利涉大川。</p><p>由者從也。九以陽剛居上位，是天下之養皆從上九以養之也。厲者，上而知君賴我以養也，則恐專權僭逼，而此心無一事之或忽。下而知民由我以養也，則常握髮吐哺而此心無一時之或寧。此上九之所謂厲也。故戒之以厲，而後許之以吉也。凡易言涉大川，取幹者，以卦德也。以幹天下至健，德行恆易，以知險也。需、同人、大畜是也。取水木者，以卦體也。渙、蠱、未濟、謙，或取中爻，或取卦變是也。取中虛者，以卦象也。益、中孚、頤是也。五不可涉大川，上九利涉大川，方見五賴上九以養人。</p><p>上九以陽剛之德居尊位，六五賴其賢以養人，故有由頤之象。然位高任重，必厲而後吉，即天下有險阻亦可以濟之而不失其養也。其佔又如此。</p><h3 id="《象》曰-由頤厲吉-大有慶也。" tabindex="-1">《象》曰：由頤厲吉，大有慶也。 <a class="header-anchor" href="#《象》曰-由頤厲吉-大有慶也。" aria-label="Permalink to “《象》曰：由頤厲吉，大有慶也。”">​</a></h3><p>得所養下之慶，亦君上之慶，故大。</p>',37)])])}const f=e(t,[["render",h]]);export{_ as __pageData,f as default};
